CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS businesses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  currency text NOT NULL DEFAULT 'IRR_TOMAN',
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','disabled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS branches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id),
  name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Tehran', status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id, name)
);

CREATE TABLE IF NOT EXISTS users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL,
  display_name text NOT NULL, status text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited','active','suspended','disabled','pending_verification')),
  last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, label text NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, label text NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id, permission_id));
CREATE TABLE IF NOT EXISTS business_memberships (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id, user_id, role_id)
);
CREATE TABLE IF NOT EXISTS user_branch_assignments (user_id uuid NOT NULL REFERENCES users(id), branch_id uuid NOT NULL REFERENCES branches(id), PRIMARY KEY(user_id, branch_id));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS workers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), user_id uuid REFERENCES users(id), branch_id uuid REFERENCES branches(id), name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, phone text, customer_type text NOT NULL DEFAULT 'walk_in', credit_status text NOT NULL DEFAULT 'none', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), customer_id uuid REFERENCES customers(id), plate text NOT NULL, vehicle_type text NOT NULL, brand text, model text, colour text, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id, plate));

CREATE TABLE IF NOT EXISTS services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, description text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id, name));
CREATE TABLE IF NOT EXISTS service_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid NOT NULL REFERENCES services(id), vehicle_type text NOT NULL, amount_toman bigint NOT NULL CHECK (amount_toman >= 0), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_by uuid REFERENCES users(id), UNIQUE(service_id, vehicle_type, effective_from));
CREATE TABLE IF NOT EXISTS service_packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS commission_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), service_id uuid REFERENCES services(id), role_key text NOT NULL, commission_type text NOT NULL CHECK (commission_type IN ('percentage','fixed')), percentage_basis_points integer NOT NULL DEFAULT 0 CHECK (percentage_basis_points >= 0), fixed_amount_toman bigint NOT NULL DEFAULT 0 CHECK (fixed_amount_toman >= 0), pool_limit_basis_points integer, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_by uuid REFERENCES users(id));

CREATE TABLE IF NOT EXISTS shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid NOT NULL REFERENCES branches(id), manager_id uuid NOT NULL REFERENCES users(id), shift_type text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','closing_review','closed','reopened')), opening_cash_toman bigint NOT NULL DEFAULT 0, actual_cash_toman bigint, opened_at timestamptz, closed_at timestamptz, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS shift_workers (shift_id uuid NOT NULL REFERENCES shifts(id) ON DELETE CASCADE, worker_id uuid NOT NULL REFERENCES workers(id), PRIMARY KEY(shift_id, worker_id));
CREATE TABLE IF NOT EXISTS service_bays (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), name text NOT NULL, status text NOT NULL DEFAULT 'active', UNIQUE(branch_id, name));
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid NOT NULL REFERENCES branches(id), shift_id uuid REFERENCES shifts(id), customer_id uuid REFERENCES customers(id), vehicle_id uuid REFERENCES vehicles(id), code text NOT NULL, status text NOT NULL DEFAULT 'waiting', payment_status text NOT NULL DEFAULT 'unpaid', original_price_toman bigint NOT NULL DEFAULT 0, discount_toman bigint NOT NULL DEFAULT 0, final_price_toman bigint NOT NULL DEFAULT 0, assigned_bay_id uuid REFERENCES service_bays(id), notes text, existing_damage text, price_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, quality_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid REFERENCES users(id), updated_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, version integer NOT NULL DEFAULT 1, UNIQUE(business_id, code));
CREATE TABLE IF NOT EXISTS job_services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, service_id uuid REFERENCES services(id), service_name_snapshot text NOT NULL, price_snapshot_toman bigint NOT NULL, discount_toman bigint NOT NULL DEFAULT 0, net_revenue_toman bigint NOT NULL, UNIQUE(job_id, service_id));
CREATE TABLE IF NOT EXISTS worker_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, job_service_id uuid REFERENCES job_services(id), worker_id uuid NOT NULL REFERENCES workers(id), role_key text NOT NULL, commission_type text NOT NULL, commission_percentage_basis_points integer NOT NULL DEFAULT 0, fixed_amount_toman bigint NOT NULL DEFAULT 0, calculation_base_toman bigint NOT NULL DEFAULT 0, estimated_amount_toman bigint NOT NULL DEFAULT 0, final_amount_toman bigint, status text NOT NULL DEFAULT 'assigned', started_at timestamptz, completed_at timestamptz, quality_result text, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS quality_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), inspector_id uuid NOT NULL REFERENCES users(id), outcome text NOT NULL, checklist_version text NOT NULL, checklist jsonb NOT NULL DEFAULT '[]'::jsonb, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rework_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), requested_by uuid NOT NULL REFERENCES users(id), assigned_worker_id uuid REFERENCES workers(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);

CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid NOT NULL REFERENCES branches(id), job_id uuid NOT NULL REFERENCES jobs(id), created_by uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'pending', total_amount_toman bigint NOT NULL CHECK(total_amount_toman >= 0), tip_amount_toman bigint NOT NULL DEFAULT 0 CHECK(tip_amount_toman >= 0), idempotency_key text NOT NULL, confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id, idempotency_key));
CREATE TABLE IF NOT EXISTS payment_parts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id) ON DELETE CASCADE, method text NOT NULL CHECK(method IN ('cash','card','bank_transfer','customer_credit','membership_credit')), amount_toman bigint NOT NULL CHECK(amount_toman > 0), reference text);
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), job_id uuid NOT NULL REFERENCES jobs(id), requested_by uuid NOT NULL REFERENCES users(id), amount_toman bigint NOT NULL CHECK(amount_toman > 0), reason text NOT NULL, status text NOT NULL DEFAULT 'pending', approved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_registers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid NOT NULL UNIQUE REFERENCES shifts(id), opening_cash_toman bigint NOT NULL DEFAULT 0, actual_closing_cash_toman bigint, expected_closing_cash_toman bigint, difference_toman bigint, explanation text, review_status text NOT NULL DEFAULT 'not_required', reviewed_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS cash_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cash_register_id uuid NOT NULL REFERENCES cash_registers(id), type text NOT NULL CHECK(type IN ('payment','refund','expense','added','removed')), amount_toman bigint NOT NULL CHECK(amount_toman > 0), reference text, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), job_id uuid REFERENCES jobs(id), category text NOT NULL, amount_toman bigint NOT NULL CHECK(amount_toman >= 0), payment_source text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'draft', created_by uuid NOT NULL REFERENCES users(id), approved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), name text NOT NULL, unit text NOT NULL, minimum_stock integer NOT NULL DEFAULT 0, average_cost_toman bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inventory_item_id uuid NOT NULL REFERENCES inventory_items(id), type text NOT NULL CHECK(type IN ('purchase','usage','waste','transfer_in','transfer_out','adjustment','return')), quantity integer NOT NULL CHECK(quantity > 0), unit_cost_toman bigint NOT NULL DEFAULT 0, reason text NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), idempotency_key text NOT NULL, UNIQUE(inventory_item_id, idempotency_key));
CREATE TABLE IF NOT EXISTS suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, phone text, status text NOT NULL DEFAULT 'active');

CREATE TABLE IF NOT EXISTS payroll_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), starts_on date NOT NULL, ends_on date NOT NULL, status text NOT NULL DEFAULT 'draft', UNIQUE(business_id, starts_on, ends_on));
CREATE TABLE IF NOT EXISTS worker_earnings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), worker_id uuid NOT NULL REFERENCES workers(id), job_id uuid REFERENCES jobs(id), assignment_id uuid REFERENCES worker_assignments(id), earning_type text NOT NULL, gross_amount_toman bigint NOT NULL, adjustment_toman bigint NOT NULL DEFAULT 0, final_amount_toman bigint NOT NULL, status text NOT NULL DEFAULT 'estimated', earned_at timestamptz, payroll_period_id uuid REFERENCES payroll_periods(id), paid_amount_toman bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payroll_statements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_period_id uuid NOT NULL REFERENCES payroll_periods(id), worker_id uuid NOT NULL REFERENCES workers(id), opening_unpaid_toman bigint NOT NULL DEFAULT 0, salary_toman bigint NOT NULL DEFAULT 0, commissions_toman bigint NOT NULL DEFAULT 0, tips_toman bigint NOT NULL DEFAULT 0, bonuses_toman bigint NOT NULL DEFAULT 0, deductions_toman bigint NOT NULL DEFAULT 0, advances_toman bigint NOT NULL DEFAULT 0, total_payable_toman bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft', approved_by uuid REFERENCES users(id), paid_amount_toman bigint NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1, UNIQUE(payroll_period_id, worker_id));
CREATE TABLE IF NOT EXISTS payroll_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_statement_id uuid NOT NULL REFERENCES payroll_statements(id), amount_toman bigint NOT NULL CHECK(amount_toman > 0), method text NOT NULL, paid_by uuid NOT NULL REFERENCES users(id), idempotency_key text NOT NULL UNIQUE, paid_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_credit_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL UNIQUE REFERENCES customers(id), credit_limit_toman bigint NOT NULL DEFAULT 0, outstanding_toman bigint NOT NULL DEFAULT 0, approved_by uuid REFERENCES users(id), status text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS customer_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), customer_id uuid NOT NULL REFERENCES customers(id), job_id uuid REFERENCES jobs(id), amount_toman bigint NOT NULL, due_on date NOT NULL, status text NOT NULL DEFAULT 'open');

CREATE TABLE IF NOT EXISTS ledger_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), event_type text NOT NULL, source_type text NOT NULL, source_id uuid NOT NULL, idempotency_key text NOT NULL UNIQUE, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES ledger_transactions(id) ON DELETE CASCADE, account_code text NOT NULL, debit_toman bigint NOT NULL DEFAULT 0 CHECK(debit_toman >= 0), credit_toman bigint NOT NULL DEFAULT 0 CHECK(credit_toman >= 0), CHECK ((debit_toman = 0) <> (credit_toman = 0)));
CREATE TABLE IF NOT EXISTS approval_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), request_type text NOT NULL, related_type text NOT NULL, related_id uuid NOT NULL, requested_by uuid NOT NULL REFERENCES users(id), approver_id uuid REFERENCES users(id), reason text NOT NULL, financial_effect_toman bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft', submitted_at timestamptz, decided_at timestamptz);
CREATE TABLE IF NOT EXISTS attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), related_type text NOT NULL, related_id uuid NOT NULL, storage_key text NOT NULL UNIQUE, content_type text NOT NULL, size_bytes bigint NOT NULL, access_classification text NOT NULL DEFAULT 'private', uploaded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), user_id uuid NOT NULL REFERENCES users(id), category text NOT NULL, title text NOT NULL, detail text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid REFERENCES businesses(id), branch_id uuid REFERENCES branches(id), user_id uuid REFERENCES users(id), role_key text, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, previous_values jsonb, new_values jsonb, reason text, request_id text, ip_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS application_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), key text NOT NULL, value jsonb NOT NULL, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, updated_by uuid REFERENCES users(id), UNIQUE(business_id, key, effective_from));
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), request_hash text NOT NULL, response_status integer, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);

CREATE INDEX IF NOT EXISTS idx_jobs_branch_status ON jobs(branch_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_business_created ON jobs(business_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_customers_business_phone ON customers(business_id, phone);
CREATE INDEX IF NOT EXISTS idx_audit_business_created ON audit_events(business_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_worker_earnings_worker_period ON worker_earnings(worker_id, payroll_period_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user_unread ON notifications(user_id, read_at);

